F=Fig('arrow191');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
K=lambda lang,*v:v[{'en':0,'ur':1,'ps':2}[lang]]
def ms(lang):
 s=F.start(330)+'<path d="M260 160 Q420 40 580 160" fill="none" stroke="#90a4ae" stroke-width="40"/>'+'<path d="M300 120 Q420 30 540 120" fill="none" stroke="#b0bec5" stroke-width="22"/>'+t(420,64,K(lang,'MAGNET','مقناطیس','مقناطیس'),13)
 s+='<rect x="120" y="170" width="140" height="50" fill="#eceff1" stroke="#555" transform="rotate(-20 190 195)"/>'+line(110,230,60,250,6,'#c62828')
 s+='<path d="M200 190 Q420 60 640 220" fill="none" stroke="#c62828" stroke-width="2" stroke-dasharray="3 4"/>'+'<path d="M200 190 Q380 80 560 200" fill="none" stroke="#c62828" stroke-width="1.2" stroke-dasharray="2 4"/>'+'<path d="M200 190 Q460 40 690 200" fill="none" stroke="#c62828" stroke-width="1.2" stroke-dasharray="2 4"/>'
 s+='<rect x="630" y="220" width="40" height="30" fill="none" stroke="#555"/>'+'<rect x="640" y="275" width="140" height="45" fill="#fff" stroke="#555"/>'+'<path d="M650 312 L680 312 L684 285 L688 312 L700 312 L704 292 L708 312 L770 312" fill="none" stroke="#222"/>'+line(650,250,700,275,1)
 s+=t(100,280,K(lang,'probe','پروب','پروب'),11)+t(190,290,K(lang,'sample','نمونہ','نمونه'),11)+t(60,190,K(lang,'ion source','آئن ماخذ','د ایون سرچینه'),11)+t(140,140,K(lang,'insulator','حاجز','عایق'),11)+t(230,110,K(lang,'ion beam','آئن شعاع','د ایون وړانګه'),11)
 s+=t(270,250,K(lang,'accelerator plate','اسراع دینے والی پلیٹ','چټکوونکې پلېټ'),11)+t(270,175,K(lang,'slits','شگاف','درزونه'),11)+t(560,40,K(lang,'ions that are too heavy bend too little','بہت بھاری آئن بہت کم مڑتے ہیں','ډېر دروند ایونونه ډېر لږ کږېږي'),11)
 s+=t(380,190,K(lang,'ions that are too light bend too much','بہت ہلکے آئن بہت زیادہ مڑتے ہیں','ډېر سپک ایونونه ډېر کږېږي'),11)+t(640,80,K(lang,'flight tube','پرواز نلی','د الوتنې نل'),11)+t(700,120,K(lang,'only ions of the right mass can enter the detector','صرف درست کمیت کے آئن ڈیٹیکٹر میں داخل ہو سکتے ہیں','یوازې د سمې کتلې ایونونه موندونکي ته ننوتلی شي'),10)
 s+=t(740,210,K(lang,'detector slits','ڈیٹیکٹر شگاف','د موندونکي درزونه'),11)+t(720,240,K(lang,'detector','ڈیٹیکٹر','موندونکی'),11)+t(500,270,K(lang,'to vacuum pump','خلا پمپ کی طرف','خلا پمپ ته'),11)+t(800,300,K(lang,'recorder','ریکارڈر','ثبتوونکی'),11)
 return s+'</svg>'
def bars(lang,peaks,xmin,xmax,ymax,ticks,labels,ylab,xlab='m/z',h=240):
 X=lambda m:90+(m-xmin)/(xmax-xmin)*680;Y=lambda a:h-40-a/ymax*(h-70)
 s=F.start(h)+line(90,Y(0),780,Y(0),1.5)+line(90,Y(0),90,Y(ymax),1.5)
 for m in ticks:s+=line(X(m),Y(0),X(m),Y(0)+5)+t(X(m),Y(0)+20,str(m),11)
 for m,a in peaks:s+=line(X(m),Y(0),X(m),Y(a),3,'#1565c0')
 for m,a,lab in labels:s+=t(X(m),Y(a)-6,lab,11)
 s+=t(800,Y(0)+5,xlab,12)+f'<text x="45" y="{Y(ymax/2)}" transform="rotate(-90 45 {Y(ymax/2)})" text-anchor="middle" font-family="Arial" font-size="11">{ylab}</text>'
 return s+'</svg>'

add('… trajectory, causing them to adopt a circular path, the radius of which depends on their mass-to-charge ratio (m/z). Ions of small m/z values are deflected more than those of larger m/z. By varying the magnetic field strength, ions of a particular m/z can be selectively focused through a narrow slit onto a detector, where they are counted. A mass spectrum is the graph plotted by the mass spectrometer, with the m/z values on x-axis and the relative number of ions of each mass on the y-axis. Higher the peak of a species higher will be its abundance.','… راستے سے موڑ کر دائری راستہ اختیار کرنے پر مجبور کرتا ہے جس کا رداس ان کی کمیت اور چارج کی نسبت (m/z) پر منحصر ہے۔ کم m/z والے آئن زیادہ m/z والوں سے زیادہ مڑتے ہیں۔ مقناطیسی میدان کی طاقت بدل کر کسی خاص m/z کے آئنز کو منتخب طور پر تنگ شگاف سے ڈیٹیکٹر پر مرکوز کیا جا سکتا ہے جہاں انہیں گنا جاتا ہے۔ ماس طیف ماس سپیکٹرومیٹر کا بنایا ہوا گراف ہے جس میں x-محور پر m/z اقدار اور y-محور پر ہر کمیت کے آئنز کی نسبتی تعداد ہوتی ہے۔ کسی نوع کی چوٹی جتنی اونچی ہو اس کی کثرت اتنی زیادہ ہوگی۔','… لارې څخه اړوي او دایروي لاره غوره کولو ته یې اړ باسي چې شعاع یې د دوی د کتلې او چارج په نسبت (m/z) پورې اړه لري. د کوچني m/z ایونونه د لوی m/z په پرتله ډېر کږېږي. د مقناطیسي ساحې د قوت په بدلولو د یوه ځانګړي m/z ایونونه په ټاکلي ډول له یوه نري درز څخه پر موندونکي متمرکز کېدای شي چې هلته شمېرل کېږي. ماس طیف د ماس سپکټرومیټر له خوا رسم شوی ګراف دی چې د x-محور پر m/z ارزښتونه او د y-محور پر د هرې کتلې د ایونونو نسبي شمېر لري. د یوه ډول څوکه څومره لوړه وي، کثرت به یې هومره زیات وي.')
visual('chem12-figure24-13',ms)
add('Figure 24.13 Schematic diagram of a Mass Spectrometer.','شکل 24.13 ماس سپیکٹرومیٹر کا خاکہ۔','شکل 24.13 د ماس سپکټرومیټر سکیماتیک انځور.')
add('Mass spectrum helps in finding the number of isotopes of an element and also their relative abundances. The mass spectrum of neon shows three peaks with m/z equal to 20, 21, and 22 which correspond to ²⁰Ne, ²¹Ne and ²²Ne respectively. Neon–20 is the most abundant and Neon–21 is the least abundant isotope as clear from the heights of their peaks.','ماس طیف کسی عنصر کے آئسوٹوپس کی تعداد اور ان کی نسبتی کثرت معلوم کرنے میں مدد دیتا ہے۔ نیون کا ماس طیف m/z کے 20، 21 اور 22 کے برابر تین چوٹیاں دکھاتا ہے جو بالترتیب ²⁰Ne، ²¹Ne اور ²²Ne کے مطابق ہیں۔ چوٹیوں کی اونچائی سے واضح ہے کہ نیون–20 سب سے زیادہ اور نیون–21 سب سے کم پایا جانے والا آئسوٹوپ ہے۔','ماس طیف د یوه عنصر د ایزوټوپونو شمېر او د هغوی نسبي کثرت په موندلو کې مرسته کوي. د نیون ماس طیف درې څوکې ښيي چې m/z یې 20، 21 او 22 دي او په ترتیب سره له ²⁰Ne، ²¹Ne او ²²Ne سره سمون لري. د څوکو له لوړوالي څرګندېږي چې نیون–20 تر ټولو ډېر او نیون–21 تر ټولو لږ موندل کېدونکی ایزوټوپ دی.')
visual('chem12-figure24-14',lambda l:bars(l,[(20,90.92),(21,0.57),(22,8.82)],18,24,100,[20,21,22],[(20,90.92,'90.92%'),(21,4,'0.57%'),(22,8.82,'8.82%')],K(l,'Abundance (%)','کثرت (%)','کثرت (%)')))
add('Figure 24.14 Mass spectrum of Neon.','شکل 24.14 نیون کا ماس طیف۔','شکل 24.14 د نیون ماس طیف.')
add('When a molecule is introduced into mass spectrometer, the molecular ion (M⁺) is produced due to loss of an electron. The molecular ion has the highest m/z value that represents the molecular mass of molecule. In addition to the molecular ion, more ions are produced due to fragmentation of the molecule. Fragmentation occurs due to rupture of chemical bonds. A mass spectrum of chlorine molecule is given in Figure 24.15 shows that there are two isotopes of chlorine ³⁵Cl (m/z = 35) and ³⁷Cl (m/z = 37) and three types of chlorine molecules, ³⁵Cl–³⁵Cl (m/z = 70), ³⁵Cl–³⁷Cl (m/z = 72) and ³⁷Cl–³⁷Cl (m/z = 74).','جب کوئی سالمہ ماس سپیکٹرومیٹر میں داخل کیا جاتا ہے تو ایک الیکٹران کے نکلنے سے سالماتی آئن (M⁺) بنتا ہے۔ سالماتی آئن کی m/z قدر سب سے زیادہ ہوتی ہے جو سالمے کی سالماتی کمیت ظاہر کرتی ہے۔ سالماتی آئن کے علاوہ سالمے کے ٹکڑے ہونے سے مزید آئن بنتے ہیں۔ ٹکڑے ہونا کیمیائی بندوں کے ٹوٹنے سے ہوتا ہے۔ شکل 24.15 میں دیا گیا کلورین سالمے کا ماس طیف ظاہر کرتا ہے کہ کلورین کے دو آئسوٹوپ ³⁵Cl (m/z = 35) اور ³⁷Cl (m/z = 37) اور کلورین کے تین قسم کے سالمات ³⁵Cl–³⁵Cl (m/z = 70)، ³⁵Cl–³⁷Cl (m/z = 72) اور ³⁷Cl–³⁷Cl (m/z = 74) ہیں۔','کله چې یو مالیکول ماس سپکټرومیټر ته ننویستل شي، د یوه الکترون له لاسه ورکولو له امله مالیکولي ایون (M⁺) تولیدېږي. مالیکولي ایون تر ټولو لوړ m/z ارزښت لري چې د مالیکول مالیکولي کتله ښيي. له مالیکولي ایون سربېره، د مالیکول د ټوټې کېدو له امله نور ایونونه تولیدېږي. ټوټې کېدل د کیمیاوي تړونونو د شلېدو له امله کېږي. په شکل 24.15 کې ورکړل شوی د کلورین مالیکول ماس طیف ښيي چې د کلورین دوه ایزوټوپونه ³⁵Cl (m/z = 35) او ³⁷Cl (m/z = 37) او درې ډوله کلورین مالیکولونه ³⁵Cl–³⁵Cl (m/z = 70)، ³⁵Cl–³⁷Cl (m/z = 72) او ³⁷Cl–³⁷Cl (m/z = 74) شته.')
visual('chem12-figure24-15',lambda l:bars(l,[(35,100),(37,33),(70,100),(72,65),(74,11)],5,80,110,[10,20,30,40,50,60,70],[(36,105,K(l,'Isotopes Cl-35 and Cl-37','آئسوٹوپ Cl-35 اور Cl-37','ایزوټوپونه Cl-35 او Cl-37')),(72,105,K(l,'Molecules Cl₂-70, Cl₂-72, Cl₂-74','سالمات Cl₂-70، Cl₂-72، Cl₂-74','مالیکولونه Cl₂-70، Cl₂-72، Cl₂-74'))],K(l,'relative abundance','نسبتی کثرت','نسبي کثرت')))
add('Figure 24.15 Mass spectrum of chlorine (Cl₂).','شکل 24.15 کلورین (Cl₂) کا ماس طیف۔','شکل 24.15 د کلورین (Cl₂) ماس طیف.')
add('The fragmentation pattern of a molecule gives an idea of the structure of the molecule. Thus mass spectrometry is very helpful in the identification of molecular structures as well. Mass spectrum of methyl alcohol is given in Figure 24.16.','سالمے کے ٹکڑے ہونے کا انداز سالمے کی ساخت کا اندازہ دیتا ہے۔ یوں ماس سپیکٹرومیٹری سالماتی ساختوں کی شناخت میں بھی بہت مددگار ہے۔ میتھائل الکوحل کا ماس طیف شکل 24.16 میں دیا گیا ہے۔','د مالیکول د ټوټې کېدو بڼه د مالیکول د جوړښت اټکل ورکوي. په دې توګه ماس سپکټرومیټري د مالیکولي جوړښتونو په پېژندلو کې هم ډېره ګټوره ده. د میتایل الکول ماس طیف په شکل 24.16 کې ورکړل شوی.')
visual('chem12-figure24-16',lambda l:bars(l,[(12,2),(13,3),(14,5),(15,10),(17,2),(28,8),(29,45),(30,5),(31,100),(32,68)],0,40,100,[0,10,20,30,40],[(13,10,'C⁺H'),(14,25,'C⁺H₂'),(16,15,'CH₃⁺'),(18,12,'O⁺H'),(28,14,'CO⁺'),(29,50,'COH⁺'),(31,105,'CH₂OH⁺'),(34,75,'CH₃OH⁺'),(37,25,'CHOH⁺')],K(l,'Rel. Abundance','نسبتی کثرت','نسبي کثرت'),h=260))
